import type { BudgetId, CategoryId, HeartLevel, Interest, Occasion, Relationship, Vibe } from './types';

export type { CategoryId };

/**
 * The admin-facing product record: what Katya fills in (CSV, JSON or a future
 * admin screen). Everything except id, title, price and category is optional;
 * missing recommendation fields are generated by `generateRules` (rules.ts).
 * `compileProduct` turns a Product into the CatalogItem the scoring engine reads.
 */
export interface Product {
  /** Unique slug, lowercase letters, digits and hyphens. Generated from the title on import if left blank. */
  id: string;
  title: string;
  /** One short line shown under the title (max 140 characters). */
  blurb: string;
  /** Whole AED, gift wrap not included. */
  price: number;
  category: CategoryId;
  /** https URL or a site path such as /products/rose-candle.jpg. Shown instead of the category icon. */
  imageUrl?: string;
  /** Free-form labels ("candle", "custom", "eid"). Known tags feed the rule generator; others are kept for search. */
  tags?: string[];

  // ---- Optional overrides. When set they REPLACE what would be generated. ----
  /** Which of the ten interests this item matches (+3 each in scoring). Up to 3. */
  interests?: Interest[];
  /** Which vibes it suits (+2 each). Up to 3. */
  vibes?: Vibe[];
  /** Occasions it gets a +1 boost for. */
  occasions?: Occasion[];
  /** Only offered for these recipients. Leave empty for everyone. */
  recipients?: Relationship[];
  /** Hide it from budgets below this tier (price already hides it from budgets that cannot afford it). */
  minBudget?: BudgetId;
  /** Unlock requirements: shown only at this personalisation level or higher, and/or only when a photo was uploaded. */
  unlock?: { hearts?: HeartLevel; photo?: boolean };
  /** false hides the product (also hides a built-in product with the same id). Default true. */
  active?: boolean;
}

// Each record forces a complete list: adding a union member without adding it here is a compile error.
const CATEGORY_SET: Record<CategoryId, true> = {
  coffee: true, selfcare: true, flowers: true, beauty: true, wellness: true, home: true, books: true, treats: true,
  tech: true, travel: true, candles: true, cakes: true, sweets: true, experiences: true, personalised: true,
};
const INTEREST_SET: Record<Interest, true> = {
  coffee: true, selfcare: true, flowers: true, beauty: true, wellness: true, home: true, books: true, treats: true, tech: true, travel: true,
};
const VIBE_SET: Record<Vibe, true> = { cozy: true, elegant: true, joyful: true, romantic: true, minimal: true, natural: true };
const OCCASION_SET: Record<Occasion, true> = { birthday: true, thankyou: true, celebration: true, newbeginning: true, anniversary: true, justbecause: true };
const RELATIONSHIP_SET: Record<Relationship, true> = { partner: true, friend: true, family: true, colleague: true, other: true };

export const CATEGORY_IDS = Object.keys(CATEGORY_SET) as CategoryId[];
export const INTERESTS = Object.keys(INTEREST_SET) as Interest[];
export const VIBES = Object.keys(VIBE_SET) as Vibe[];
export const OCCASIONS = Object.keys(OCCASION_SET) as Occasion[];
export const RELATIONSHIPS = Object.keys(RELATIONSHIP_SET) as Relationship[];
export const HEART_LEVELS: HeartLevel[] = [1, 2, 3];

export const LIMITS = { title: 60, blurb: 140, interests: 3, vibes: 3, occasions: 3, price: 20000 } as const;
